import{_ as s,o as e,c as n,ag as l}from"./chunks/framework.DUTPmUpA.js";const b=JSON.parse('{"title":"Передача значенийabilityValues ​​в Lua","description":"","frontmatter":{"title":"Передача значенийabilityValues ​​в Lua","author":"Noya","steamId":"76561198046984233","date":"12.12.2014"},"headers":[],"relativePath":"abilities/passing-abilityvalues-values-into-lua.md","filePath":"abilities/passing-abilityvalues-values-into-lua.md"}'),i={name:"abilities/passing-abilityvalues-values-into-lua.md"};function t(p,a,o,u,r,c){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="передача-значенииabilityvalues-в-lua" tabindex="-1">Передача значенийabilityValues в Lua <a class="header-anchor" href="#передача-значенииabilityvalues-в-lua" aria-label="Permalink to &quot;Передача значенийabilityValues в Lua&quot;">​</a></h1><p>Учитывая этот блок «AbilityValues» в способности:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;AbilityValues&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;radius&quot; &quot;300&quot;</span></span>
<span class="line"><span>  &quot;mana_per_second&quot; &quot;5 10 15 20&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Есть две функции для их подключения: <code>GetSpecialValueFor</code> и <code>GetLevelSpecialValueFor</code>. Оба применяются к способности.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>local ability = event.ability</span></span>
<span class="line"><span>local radius = ability:GetSpecialValueFor(&quot;radius&quot;)</span></span>
<span class="line"><span>local mana_per_second = ability:GetLevelSpecialValueFor(&quot;mana_per_second&quot;, (ability:GetLevel() - 1))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Первый получит значение <strong>текущего уровня</strong> способности.</p><p>Второй получит значение для <strong>указанного уровня</strong> способности.</p><p>Первый из них является наиболее распространенным, и его следует <strong>использовать каждый раз</strong>, если только вам не требуется значение для определенного уровня.</p><p>Обратите внимание на использование <code>(ability:GetLevel() - 1)</code> в качестве второго параметра (который сообщает сценарию, какой уровень выбрать). Это необходимо, поскольку уровни способностей имеют индекс 1, а <code>GetLevelSpecialValueFor</code> — индекс 0.</p>`,9)])])}const m=s(i,[["render",t]]);export{b as __pageData,m as default};
